"""The project graph (docs/graph.html, generated by the html-doc skill, not by this site) as a result of the search."""

TEXT = {
    "en": ("Project graph (interactive)", "Files, classes, functions, calls and tests of libutils, in 2D or 3D.",
           "graph dependencies includes calls nodes 3d interactive"),
    "fr": ("Graphe du projet (interactif)", "Fichiers, classes, fonctions, appels et tests de libutils, en 2D ou en 3D.",
           "graphe dépendances includes appels nœuds 3d interactif"),
}

def search_entries(ctx: object) -> list[dict]:
    return [{"k": "page", "l": lang, "t": TEXT[lang][0], "d": TEXT[lang][1], "u": "graph.html", "x": TEXT[lang][2]} for lang in ctx.langs]
